      const line = [];
      for (let c = 0; c < this.w; c++) {
        const ch = rows[r][c];
        if (ch === '@' || ch === '+') this.player = [r, c];
        if (ch === 'B' || ch === '*') this.crates.add(r * this.w + c);
        line.push(ch === '#' ? '#' : ch === '~' ? '~' : ch === '_' || ch === '+' || ch === '*' ? '_' : '.');
      }
